                        if (newlo2 > lo[i-1]) { lo[i-1] = newlo2; changed = 1; }
                    } else { // even: a[i] > a[i-1]
                        long long newlo = (broken[i-1] ? lo[i-1] : a[i-1]) + 1;
                        if (newlo > lo[i]) { lo[i] = newlo; changed = 1; }
                        long long newhi2 = (broken[i] ? hi[i] : a[i]) - 1;
                        if (newhi2 < hi[i-1]) { hi[i-1] = newhi2; changed = 1; }
