typedef long long ll;

static int is_x(const char *s) {
    return s[0] == 'x' && s[1] == '\0';
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    ll *a = (ll *)malloc((n + 1) * sizeof(ll));
    int *known = (int *)malloc((n + 1) * sizeof(int));
    char buf[64];

    for (int i = 1; i <= n; i++) {
        if (scanf("%63s", buf) != 1) return 0;
        if (is_x(buf)) {
            known[i] = 0;
            a[i] = 0;
        } else {
            known[i] = 1;
            a[i] = atoll(buf);
        }
    }

    /* Check consistency of already known adjacent values */
    for (int i = 1; i < n; i++) {
        if (known[i] && known[i + 1]) {
            if (i % 2 == 1) {
                if (!(a[i] < a[i + 1])) {
                    printf("none\n");
                    free(a);
                    free(known);
                    return 0;
                }
            } else {
                if (!(a[i] > a[i + 1])) {
                    printf("none\n");
                    free(a);
                    free(known);
                    return 0;
                }
            }
        }
    }

    int multiple = 0;
    int i = 1;

    while (i <= n) {
        if (known[i]) {
            i++;
            continue;
        }

        int l = i;
        while (i <= n && !known[i]) i++;
        int r = i - 1;

        ll low = LLONG_MIN / 4;
        ll high = LLONG_MAX / 4;

        /* Constraint from left neighbor */
        if (l > 1 && known[l - 1]) {
            ll v = a[l - 1];
            if ((l - 1) % 2 == 1) {
                /* a[l-1] < a[l] */
                low = maxll(low, v + 1);
            } else {
                /* a[l-1] > a[l] */
                high = minll(high, v - 1);
            }
        }

        /* Constraint from right neighbor */
        if (r < n && known[r + 1]) {
            ll v = a[r + 1];
            if (r % 2 == 1) {
                /* a[r] < a[r+1] */
                high = minll(high, v - 1);
            } else {
                /* a[r] > a[r+1] */
                low = maxll(low, v + 1);
            }
        }

        if (low > high) {
            printf("none\n");
            free(a);
            free(known);
            return 0;
        }

        /* Inside a block of unknowns, values can alternate between two levels.
           Any integer x in [low, high] can be used for the first position,
           then the rest can be chosen as x,x+1,x,x+1... or x,x-1,... as needed.
           Since consecutive relations are only strict alternating inequalities,
           a solution exists iff interval non-empty, and it is unique iff exactly one x works
           and block length == 1 with both sides forcing it uniquely.

           More generally:
           - If block length >= 2, there are always multiple solutions whenever one exists,
             because after choosing a valid first value, the next can be any integer satisfying
             strict inequality, giving infinitely many choices.
           - If block length == 1, uniqueness happens only when low == high.
        */
        int len = r - l + 1;
        if (len >= 2) {
            multiple = 1;
        } else {
            if (low < high) multiple = 1;
        }
    }

    if (multiple) printf("multiple\n");
    else printf("unique\n");

    free(a);
    free(known);
    return 0;
}

