static const long long INF = (long long)4e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<bool> known(n + 1, false);
    vector<long long> a(n + 1, 0);

    for (int i = 1; i <= n; ++i) {
        string s;
        cin >> s;
        if (s == "x" || s == "X") {
            known[i] = false;
        } else {
            known[i] = true;
            a[i] = stoll(s);
        }
    }

    // Transform to monotone constraints:
    // b[i] =  a[i] for odd i
    // b[i] = -a[i] for even i
    // Then required condition becomes b[i] < b[i+1] for all i.
    vector<long long> b(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        if (known[i]) b[i] = (i % 2 ? a[i] : -a[i]);
    }

    // Bounds for each position in transformed sequence.
    // Need a strictly increasing integer sequence.
    // If L[i] == R[i], unique at i; otherwise multiple possibilities somewhere.
    vector<long long> L(n + 2, -INF), R(n + 2, INF);

    // Known values fix bounds.
    for (int i = 1; i <= n; ++i) {
        if (known[i]) L[i] = R[i] = b[i];
    }

    // Forward pass: b[i] >= b[i-1] + 1
    for (int i = 2; i <= n; ++i) {
        if (L[i - 1] > -INF / 2) {
            L[i] = max(L[i], L[i - 1] + 1);
        }
    }

    // Backward pass: b[i] <= b[i+1] - 1
    for (int i = n - 1; i >= 1; --i) {
        if (R[i + 1] < INF / 2) {
            R[i] = min(R[i], R[i + 1] - 1);
        }
    }

    // Another forward/backward tightening to propagate fixed points through unknowns.
    for (int i = 2; i <= n; ++i) {
        if (L[i - 1] > -INF / 2) L[i] = max(L[i], L[i - 1] + 1);
        if (R[i] < L[i]) {
            cout << "none\n";
            return 0;
        }
    }
    for (int i = n - 1; i >= 1; --i) {
        if (R[i + 1] < INF / 2) R[i] = min(R[i], R[i + 1] - 1);
        if (R[i] < L[i]) {
            cout << "none\n";
            return 0;
        }
    }

    // Final feasibility check:
    for (int i = 1; i < n; ++i) {
        if (L[i] >= R[i + 1]) {
            // Need some x_i < x_{i+1}; if even max left >= min right, impossible.
            // But maybe exact choices still possible if intervals overlap differently?
            // Since all constraints are already propagated as L[i+1] >= L[i]+1 and R[i] <= R[i+1]-1,
            // checking interval consistency is enough.
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (L[i] > R[i]) {
            cout << "none\n";
            return 0;
        }
    }

    bool unique = true;
    for (int i = 1; i <= n; ++i) {
        if (L[i] != R[i]) {
            unique = false;
            break;
        }
    }

    cout << (unique ? "unique" : "ambiguous") << '\n';
    return 0;
}

import java.util.Scanner;

public class AudioRecovery {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] tokens = new String[n];
        for (int i = 0; i < n; i++) {
            tokens[i] = sc.next();
        }
        sc.close();

        int[] values = new int[n];
        boolean[] known = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (!tokens[i].equals("x")) {
                values[i] = Integer.parseInt(tokens[i]);
                known[i] = true;
            }
        }

        boolean possible = true;
        boolean unique = true;

        for (int i = 0; i < n; i++) {
            if (!known[i]) {
                int low = Integer.MIN_VALUE;
                int high = Integer.MAX_VALUE;

                // Check left neighbor
                if (i > 0) {
                    if ((i + 1) % 2 == 1) { // odd index (1-based), should be less than neighbor
                        high = Math.min(high, values[i - 1] - 1);
                    } else { // even index, should be greater than neighbor
                        low = Math.max(low, values[i - 1] + 1);
                    }
                }

                // Check right neighbor
                if (i < n - 1 && known[i + 1]) {
                    if ((i + 1) % 2 == 1) { // odd index
                        high = Math.min(high, values[i + 1] - 1);
                    } else { // even index
                        low = Math.max(low, values[i + 1] + 1);
                    }
                }

                if (low > high) {
                    possible = false;
                    break;
                }

                long count = 0;
                if (low == Integer.MIN_VALUE && high == Integer.MAX_VALUE) {
                    count = Long.MAX_VALUE; // effectively infinite
                } else if (low == Integer.MIN_VALUE) {
                    count = (long) high - Integer.MIN_VALUE + 1;
                } else if (high == Integer.MAX_VALUE) {
                    count = (long) Integer.MAX_VALUE - low + 1;
                } else {
                    count = (long) high - low + 1;
                }

                if (count > 1) {
                    unique = false;
                }
            }
        }

        if (!possible) {
            System.out.println("impossible");
        } else if (!unique) {
            System.out.println("multiple");
        } else {
            System.out.println("unique");
        }
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            int n = parts.length;
            int[] a = new int[n];
            List<Integer> unknowns = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                if (parts[i].equals("x")) { a[i] = -1; unknowns.add(i); }
                else a[i] = Integer.parseInt(parts[i]);
            }
            // Try all combinations of 0-9 for unknowns
            int count = 0;
            int[] vals = new int[unknowns.size()];
            // BFS/enumerate
            count = enumerate(a, unknowns, vals, 0, n);
            if (count == 0) System.out.println("impossible");
            else if (count == 1) System.out.println("unique");
            else System.out.println("ambiguous");
        }
    }
    static int enumerate(int[] a, List<Integer> unknowns, int[] vals, int idx, int n) {
        if (idx == unknowns.size()) return check(a, n) ? 1 : 0;
        int pos = unknowns.get(idx);
        int total = 0;
        for (int v = 0; v <= 9; v++) {
            a[pos] = v;
            total += enumerate(a, unknowns, vals, idx+1, n);
            if (total > 1) { a[pos] = -1; return total; }
        }
        a[pos] = -1;
        return total;
    }
    static boolean check(int[] a, int n) {
        for (int i = 0; i < n; i++) {
            int pos = i+1;
            if (pos % 2 == 1) { // odd: less than neighbors
                if (i > 0 && a[i] >= a[i-1]) return false;
                if (i < n-1 && a[i] >= a[i+1]) return false;
            } else { // even: greater than neighbors
                if (i > 0 && a[i] <= a[i-1]) return false;
                if (i < n-1 && a[i] <= a[i+1]) return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static final long INF = (long) 4e18;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);

        long[] a = new long[n + 1];
        boolean[] known = new boolean[n + 1];

        for (int i = 1; i <= n; i++) {
            String s = fs.next();
            if (s.equals("x")) {
                known[i] = false;
            } else {
                known[i] = true;
                a[i] = Long.parseLong(s);
            }
        }

        // Transform:
        // b[i] = a[i] if i odd, -a[i] if i even
        // Then requirement becomes b[1] < b[2] < ... < b[n]
        long[] b = new long[n + 1];
        boolean[] bk = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            bk[i] = known[i];
            if (known[i]) {
                b[i] = (i % 2 == 1) ? a[i] : -a[i];
            }
        }

        // Check known sequence is strictly increasing.
        long last = -INF;
        for (int i = 1; i <= n; i++) {
            if (bk[i]) {
                if (b[i] <= last) {
                    System.out.println("none");
                    return;
                }
                last = b[i];
            }
        }

        boolean multiple = false;

        int i = 1;
        while (i <= n) {
            if (bk[i]) {
                i++;
                continue;
            }
            int l = i;
            while (i <= n && !bk[i]) i++;
            int r = i - 1;

            long L = -INF;
            long R = INF;
            if (l - 1 >= 1 && bk[l - 1]) L = b[l - 1];
            if (r + 1 <= n && bk[r + 1]) R = b[r + 1];

            int len = r - l + 1;

            // Need strictly increasing integers x1 < x2 < ... < xlen with L < x1 and xlen < R
            // Count existence by checking if there are at least len integers in (L, R)
            // i.e. R - L - 1 >= len
            if (R != INF && L != -INF) {
                long gap = R - L - 1;
                if (gap < len) {
                    System.out.println("none");
                    return;
                }
                if (gap > len) multiple = true;
            } else {
                // Unbounded on at least one side => always infinitely many solutions for this block
                multiple = true;
            }
        }

        System.out.println(multiple ? "many" : "unique");
    }
}

