                        # i is 0-based, so odd 1-based means i%2==0
                        if i % 2 == 0: 
                            hi = min(hi, values[i-1] - 1)
                        else:
                            lo = max(lo, values[i-1] + 1)
                # If left is unknown, can't tighten bounds from that side yet
            # Right neighbor constraint
            if i < n-1:
                if values[i+1] is not None:
                    if i % 2 == 0:  # odd 1-based
                        hi = min(hi, values[i+1] - 1)
                    else:
                        lo = max(lo, values[i+1] + 1)
            # Also respect neighbors' parity constraints indirectly via bounds
            # Now also apply constraints from both sides if both known
            if i > 0 and i < n-1:
                if values[i-1] is not None and values[i+1] is not None:
                    if i % 2 == 0:  # odd position
                        hi = min(hi, values[i-1] - 1, values[i+1] - 1)
                    else:
                        lo = max(lo, values[i-1] + 1, values[i+1] + 1)
            if lo > hi:
                possible.append(set())
            else:
                possible.append(set(range(lo, hi+1)))

    # Now propagate constraints repeatedly until stable
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if values[i] is not None:
                continue
            lo, hi = -INF, INF
            # left neighbor
            if i > 0:
                if values[i-1] is not None:
                    if i % 2 == 0:
                        hi = min(hi, values[i-1] - 1)
                    else:
                        lo = max(lo, values[i-1] + 1)
                else:
                    # left unknown: pick value compatible with possible set
                    if possible[i-1]:
                        if i % 2 == 0:
                            hi = min(hi, max(possible[i-1]) - 1)
                        else:
                            lo = max(lo, min(possible[i-1]) + 1)
            if i < n-1:
                if values[i+1] is not None:
                    if i % 2 == 0:
                        hi = min(hi, values[i+1] - 1)
                    else:
                        lo = max(lo, values[i+1] + 1)
                else:
                    if possible[i+1]:
                        if i % 2 == 0:
                            hi = min(hi, max(possible[i+1]) - 1)
                        else:
                            lo = max(lo, min(possible[i+1]) + 1)
            new_set = set(range(max(lo, -INF), min(hi, INF)+1))
            if new_set != possible[i]:
                possible[i] = new_set
                changed = True

    # Check result
    all_unique = True
    impossible = False
    for p in possible:
        if not p:
            impossible = True
            break
        if len(p) > 1:
            all_unique = False

    if impossible:
        print("none")
    elif all_unique:
        print("unique")
    else:
        print("ambiguous")

